import type { Article } from "../types/article";
import { isDiscoverable } from "./authority.js";

import snapshot from "../data/articles.json";

// Generated by scripts/generate-content.js through the same loader as prerender and feeds.
const articleCache: Map<string, Article> = new Map();
const allArticles = snapshot as Article[];
export function getDiscoverableArticles(): Article[] {
  return allArticles.filter(isDiscoverable);
}
export function getAllArticles(): Article[] {
  return allArticles;
}

export function getArticleBySlug(
  category: string,
  slug: string,
): Article | null {
  const cacheKey = `${category}/${slug}`;

  if (articleCache.has(cacheKey)) {
    return articleCache.get(cacheKey)!;
  }

  const articles = getAllArticles();
  const article = articles.find(
    (a) => a.categoryPath === category && a.slug === slug,
  );

  if (article) {
    articleCache.set(cacheKey, article);
  }

  return article || null;
}

export function getArticlesByCategory(
  category: string,
  limit?: number,
): Article[] {
  const articles = getDiscoverableArticles();
  const filtered = articles.filter((a) => a.categoryPath === category);
  return limit ? filtered.slice(0, limit) : filtered;
}

export function getArticlesByTag(tag: string): Article[] {
  const articles = getDiscoverableArticles();
  return articles.filter((a) =>
    a.tags.some((value) => value.toLowerCase() === tag.toLowerCase()),
  );
}

export function getArticlesByAuthor(authorSlug: string): Article[] {
  const articles = getDiscoverableArticles();
  return articles.filter((a) => a.author_slug === authorSlug);
}

export function searchArticles(query: string): Article[] {
  const articles = getDiscoverableArticles();
  const lowerQuery = query.toLowerCase();

  return articles.filter((article) => {
    return (
      article.title.toLowerCase().includes(lowerQuery) ||
      article.dek.toLowerCase().includes(lowerQuery) ||
      article.excerpt.toLowerCase().includes(lowerQuery) ||
      article.tags.some((tag) => tag.toLowerCase().includes(lowerQuery)) ||
      article.content.toLowerCase().includes(lowerQuery)
    );
  });
}

export function getTrendingArticles(limit: number = 8): Article[] {
  const articles = getDiscoverableArticles();
  const twoDaysAgo = new Date();
  twoDaysAgo.setDate(twoDaysAgo.getDate() - 2);

  const recent = articles.filter((a) => new Date(a.published) > twoDaysAgo);
  return (recent.length ? recent : articles).slice(0, limit);
}

export function getRelatedArticles(
  article: Article,
  limit: number = 4,
): Article[] {
  const articles = getDiscoverableArticles();

  const scored = articles
    .filter((a) => a.slug !== article.slug)
    .map((a) => {
      let score = 0;
      if (a.categoryPath === article.categoryPath) score += 3;
      const sharedTags = a.tags.filter((tag) =>
        article.tags.includes(tag),
      ).length;
      score += sharedTags * 2;
      if (a.author_slug === article.author_slug) score += 1;
      return { article: a, score };
    })
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score);

  return scored.slice(0, limit).map((item) => item.article);
}

export function getAllTags(): string[] {
  const articles = getDiscoverableArticles();
  const tagSet = new Set<string>();
  articles.forEach((article) => {
    article.tags.forEach((tag) => tagSet.add(tag));
  });
  return Array.from(tagSet).sort();
}

export function getAllAuthors(): Set<string> {
  const articles = getDiscoverableArticles();
  const authorSet = new Set<string>();
  articles.forEach((article) => {
    authorSet.add(article.author_slug);
  });
  return authorSet;
}
